import sys
from collections import deque

def minStepToReachTarget(knightPos, targetPos, N):
    if knightPos == targetPos:
        return 0

    start_x, start_y = knightPos[0] - 1, knightPos[1] - 1
    target_x, target_y = targetPos[0] - 1, targetPos[1] - 1

    moves = [
        (-2, -1), (-2, 1), (-1, -2), (-1, 2),
        (1, -2), (1, 2), (2, -1), (2, 1)
    ]

    visited = [[False] * N for _ in range(N)]
    queue = deque()
    queue.append((start_x, start_y, 0))
    visited[start_x][start_y] = True

    while queue:
        x, y, steps = queue.popleft()

        for dx, dy in moves:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                if nx == target_x and ny == target_y:
                    return steps + 1

                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    return -1

def main():
    try:
        lines = sys.stdin.read().splitlines()
        idx = 0
        while idx < len(lines) and not lines[idx].strip():
            idx += 1

        if idx >= len(lines):
            return

        N = int(lines[idx].strip())
        idx += 1

        while idx < len(lines) and not lines[idx].strip():
                idx += 1
        if idx >= len(lines):
            return
        knight_line = lines[idx].strip()
        knightPos = list(map(int, knight_line.replace('{', '').replace('}', '').replace(',', ' ').split()))
        idx += 1

        while idx < len(lines) and (not lines[idx].strip() or 'target' not in lines[idx].lower()):
            idx += 1
        if idx >= len(lines):
            return

        target_line = lines[idx].strip()
        targetPos = list(map(int, target_line.replace('{', '').replace('}', '').replace(',', ' ').split()))

        result = minStepToReachTarget(knightPos, targetPos, N)
        print(result)
    except Exception:
        pass

if __name__ == "__main__":
    main()
